<script setup lang="ts">import{computed,ref}from'vue';type Candidate={id:string;name:string;job:string;note:string};
const recruiters=['谢女士','珈莉','大宁'];const candidates:Candidate[]=[{id:'mock-xm-a',name:'小明',job:'短视频编导',note:'同名同岗位场景'},{id:'mock-z-a',name:'张女士',job:'内容编导',note:'同类别岗位场景'},{id:'mock-w-a',name:'王先生',job:'直播运营',note:'历史岗位场景'},{id:'mock-l-a',name:'李同学',job:'视频剪辑',note:'普通场景'}];const recruiter=ref('谢女士'),selected=ref(0),delay=ref(false),missing=ref('none'),nickname=ref(false);const visible=ref(true);const current=computed(()=>{const item=candidates[selected.value];return{id:item.id,name:nickname.value?`${item.name} 2`:item.name,job:item.job,note:item.note}});function switchCandidate(i:number){visible.value=false;selected.value=i;history.pushState({},'',`/candidate/${candidates[i].id}`);setTimeout(()=>visible.value=true,delay.value?700:20)}
</script>
<template><div class="top"><b>Mock 招聘工作台</b><label>招聘账号 <select v-model="recruiter"><option v-for="r in recruiters" :key="r">{{r}}</option></select></label><span data-recruitment-account :data-value="recruiter">{{recruiter}}</span></div><div class="layout"><aside><button v-for="(c,i) in candidates" :key="c.id" @click="switchCandidate(i)"><strong>{{c.name}}</strong><small>{{c.job}} · {{c.note}}</small></button></aside><main v-if="visible"><div class="candidate"><span v-if="missing!=='candidate'" data-candidate-name :data-value="current.name">{{current.name}}</span><i :data-candidate-id="current.id"></i><em v-if="missing!=='job'" data-job-name :data-value="current.job">应聘：{{current.job}}</em></div><section><h3>沟通记录（仅模拟，不会被插件上传）</h3><div class="chat">您好，想了解一下您的求职意向。<br>这是本地虚构测试数据。</div><textarea placeholder="模拟招聘平台输入框"></textarea><button class="send">发送模拟消息</button></section></main><aside class="scenarios"><h3>测试场景</h3><label><input type="checkbox" v-model="delay">DOM 延迟加载</label><label><input type="checkbox" v-model="nickname">候选人改昵称</label><select v-model="missing"><option value="none">字段完整</option><option value="candidate">缺候选人</option><option value="job">缺岗位</option></select><p>切换候选人会更新 URL 并模拟 SPA。</p></aside></div></template>
